import{_ as o,C as n,o as a,c as i,a5 as s,b as d,w as r,a as l,E as p,a6 as c}from"./chunks/framework.BkFmai_x.js";const v=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1784304010000}'),u={name:"guide/architecture.md"};function h(A,e,g,b,f,P){const t=n("Mermaid");return a(),i("div",null,[e[1]||(e[1]=s(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><h2 id="project-layout" tabindex="-1">Project layout <a class="header-anchor" href="#project-layout" aria-label="Permalink to &quot;Project layout&quot;">​</a></h2><p>VaultGuard is a single .NET solution (<code>VaultGuard.sln</code>) split into a shared core and one project per front-end. Front-ends never talk to each other directly - they all sit on the same core libraries.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VaultGuard.Models/             Shared models and DTOs</span></span>
<span class="line"><span>VaultGuard.Crypto/              Key derivation and AES-256-GCM encryption</span></span>
<span class="line"><span>VaultGuard.DAL/                 Data access layer (EF Core)</span></span>
<span class="line"><span>VaultGuard.DAL.{SqlServer,MySql,Postgres}/   Database provider plugins</span></span>
<span class="line"><span>VaultGuard.Services/            Business logic (vaults, items, backups, TOTP, passkeys, permissions)</span></span>
<span class="line"><span>VaultGuard.Imports/              Import framework + per-vendor plugins (1Password, Bitwarden, ...)</span></span>
<span class="line"><span>VaultGuard.API/                 ASP.NET Core Web API</span></span>
<span class="line"><span>VaultGuard.Web/                 Blazor Server web app</span></span>
<span class="line"><span>VaultGuard.Components.Shared/    Shared Blazor UI - also hosted inside the MAUI app (Blazor Hybrid)</span></span>
<span class="line"><span>VaultGuard.WPF/                 Windows desktop app</span></span>
<span class="line"><span>VaultGuard.App/                 MAUI mobile app (Android / iOS / Windows)</span></span>
<span class="line"><span>VaultGuard.BrowserExtension/     Cross-browser extension + native messaging host</span></span></code></pre></div><h2 id="how-the-pieces-fit-together" tabindex="-1">How the pieces fit together <a class="header-anchor" href="#how-the-pieces-fit-together" aria-label="Permalink to &quot;How the pieces fit together&quot;">​</a></h2>`,5)),(a(),d(c,null,{default:r(()=>[p(t,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20Clients%0A%20%20%20%20%20%20%20%20WPF%5BWPF%20Desktop%5D%0A%20%20%20%20%20%20%20%20Web%5BBlazor%20Web%5D%0A%20%20%20%20%20%20%20%20Mobile%5BMAUI%20App%3Cbr%2F%3EAndroid%20%2F%20iOS%5D%0A%20%20%20%20%20%20%20%20Ext%5BBrowser%20Extension%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Core%5B%22Shared%20core%22%5D%0A%20%20%20%20%20%20%20%20Services%5BVaultGuard.Services%5D%0A%20%20%20%20%20%20%20%20Crypto%5BVaultGuard.Crypto%5D%0A%20%20%20%20%20%20%20%20DAL%5BVaultGuard.DAL%5D%0A%20%20%20%20%20%20%20%20Models%5BVaultGuard.Models%5D%0A%20%20%20%20end%0A%0A%20%20%20%20API%5BVaultGuard.API%3Cbr%2F%3EASP.NET%20Core%5D%0A%20%20%20%20DB%5B(SQLite%20%2F%20SQL%20Server%20%2F%3Cbr%2F%3EMySQL%20%2F%20PostgreSQL)%5D%0A%0A%20%20%20%20WPF%20--%3E%7Clocal%20vault%2C%20same%20core%7C%20Services%0A%20%20%20%20Web%20--%3E%7Cin-process%7C%20Services%0A%20%20%20%20Mobile%20--%3E%7CX-API-Key%7C%20API%0A%20%20%20%20Ext%20--%3E%7CX-API-Key%7C%20API%0A%20%20%20%20API%20--%3E%20Services%0A%20%20%20%20Services%20--%3E%20Crypto%0A%20%20%20%20Services%20--%3E%20DAL%0A%20%20%20%20DAL%20--%3E%20DB%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s('<p><strong>WPF and the Blazor web app</strong> run the shared <code>Services</code>/<code>DAL</code>/<code>Crypto</code> core <strong>in-process</strong> - there&#39;s no network hop between the UI and the business logic; the web app&#39;s &quot;server&quot; is just where that process happens to run.</p><p><strong>Mobile and the browser extension</strong> talk to <code>VaultGuard.API</code> over HTTP, authenticating with an <a href="/PasswordManagerApp/api/reference#authentication">API key</a> issued from the web app. The API hosts the exact same <code>Services</code>/<code>DAL</code>/<code>Crypto</code> core, so a request handled by the API goes through identical validation and encryption code paths as a request handled locally by WPF or the web app.</p><h2 id="data-flow-for-a-typical-read" tabindex="-1">Data flow for a typical read <a class="header-anchor" href="#data-flow-for-a-typical-read" aria-label="Permalink to &quot;Data flow for a typical read&quot;">​</a></h2><ol><li>Client asks for a vault item (in-process call for WPF/Web, or <code>GET /api/passworditems/{id}</code> for mobile/extension via the API).</li><li><code>VaultGuard.Services</code> checks the caller&#39;s <a href="/PasswordManagerApp/api/reference#authorization">permissions</a> for that resource.</li><li><code>VaultGuard.DAL</code> (EF Core) loads the encrypted row from whichever database provider is configured.</li><li><code>VaultGuard.Crypto</code> decrypts sensitive fields using a key derived from the caller&#39;s master password - which the server/API <strong>never has</strong>; decryption of secrets only happens against a session key established at sign-in (see <a href="/PasswordManagerApp/guide/security">Security Model</a>).</li><li>The client renders it - same shape, same fields, on every platform.</li></ol><h2 id="database-providers" tabindex="-1">Database providers <a class="header-anchor" href="#database-providers" aria-label="Permalink to &quot;Database providers&quot;">​</a></h2><p>SQLite is the default (zero setup, one file). <code>VaultGuard.DAL.SqlServer</code>, <code>VaultGuard.DAL.MySql</code> and <code>VaultGuard.DAL.Postgres</code> are drop-in alternatives configured from Settings - the rest of the stack (<code>Services</code>, API contracts, UI) is provider-agnostic.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><ul><li><code>VaultGuard.BackEnd.Tests</code> (NUnit) - services, controllers, crypto, seeding; the bulk of the unit/ integration suite, instrumented with <a href="https://dotnetappdev.github.io/PasswordManagerApp/allure-report/" target="_blank" rel="noreferrer">Allure</a> for dashboarded results.</li><li><code>VaultGuard.Tests.QrLogin</code>, <code>VaultGuard.Tests.OTP</code> (xUnit) - passkeys, QR login, OTP/TOTP.</li><li><code>VaultGuard.Tests.Playwright</code> (MSTest + Playwright) - drives the actual Blazor web app headlessly; also what generates the <a href="/PasswordManagerApp/platforms/web">screenshots</a> on this site.</li></ul><p>See <a href="https://github.com/dotnetappdev/PasswordManagerApp/blob/devmain/docs/TESTING.md" target="_blank" rel="noreferrer"><code>docs/TESTING.md</code></a> in the repository for the full test-running guide.</p>',9))])}const y=o(u,[["render",h]]);export{v as __pageData,y as default};
